import { useParams } from "react-router-dom";
import React, { useState, useCallback } from "react";
import axios from "axios";
import styled from "styled-components";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";

const FuelPage = () => {
  const { lorryId } = useParams();
  const [fuelDetails, setFuelDetails] = useState([]);
  const [startDate, setStartDate] = useState(null);
  const [endDate, setEndDate] = useState(null);

  const handleDateChange = (date, type) => {
    if (type === "start") {
      setStartDate(date);
    } else {
      setEndDate(date);
    }
  };

  const fetchFuelDetails = useCallback(async () => {
    if (!lorryId) {
      alert("Lorry ID is missing!");
      return;
    }

    if (!startDate || !endDate) {
      alert("Please select both start and end dates.");
      return;
    }

    try {
      const response = await axios.get(
        `http://localhost:5001/api/fuel/byRegistration/${lorryId}`, 
        {
          params: {
            startDate: startDate.toISOString().split("T")[0],
            endDate: endDate.toISOString().split("T")[0],
          },
        }
      );
      setFuelDetails(response.data);
    } catch (error) {
      console.error("Error fetching fuel details:", error);
      alert("Failed to fetch fuel details. Please try again.");
    }
  }, [lorryId, startDate, endDate]);

  return (
    <Container>
      <Header>{`Fuel Management for Lorry ID: ${lorryId}`}</Header>

      <Section>
        <h3>Filter by Date Range</h3>
        <DatePickerContainer>
          <DatePicker
            selected={startDate}
            onChange={(date) => handleDateChange(date, "start")}
            selectsStart
            startDate={startDate}
            endDate={endDate}
            dateFormat="yyyy-MM-dd"
            placeholderText="Start Date"
          />
          <DatePicker
            selected={endDate}
            onChange={(date) => handleDateChange(date, "end")}
            selectsEnd
            startDate={startDate}
            endDate={endDate}
            minDate={startDate}
            dateFormat="yyyy-MM-dd"
            placeholderText="End Date"
          />
          <Button onClick={fetchFuelDetails}>Fetch Details</Button>
        </DatePickerContainer>
      </Section>

      <Section>
        <h3>Fuel Details</h3>
        <Table>
          <thead>
            <tr>
              <th>Date</th>
              <th>Bunk Name</th>
              <th>Litres Filled</th>
              <th>Price/Litre</th>
              <th>Amount Paid</th>
            </tr>
          </thead>
          <tbody>
            {fuelDetails.length > 0 ? (
              fuelDetails.map((fuel, index) => (
                <tr key={index}>
                  <td>{fuel.date_filled}</td>
                  <td>{fuel.bunk_name}</td>
                  <td>{fuel.litres_filled}</td>
                  <td>{fuel.price_per_litre}</td>
                  <td>{fuel.amount_paid}</td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="5">No fuel details available for the selected date range.</td>
              </tr>
            )}
          </tbody>
        </Table>
      </Section>
    </Container>
  );
};

export default FuelPage;

const Container = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
`;

const Header = styled.h1`
  text-align: center;
  margin-bottom: 20px;
`;

const Section = styled.div`
  margin-bottom: 40px;
`;

const DatePickerContainer = styled.div`
  display: flex;
  gap: 20px;
  justify-content: center;
  align-items: center;
`;

const Button = styled.button`
  padding: 10px;
  font-size: 16px;
  background-color: #007bff;
  color: white;
  border: none;
  border-radius: 5px;
  cursor: pointer;

  &:hover {
    background-color: #0056b3;
  }
`;

const Table = styled.table`
  width: 100%;
  border-collapse: collapse;
  text-align: center;

  th, td {
    padding: 10px;
    border: 1px solid #ddd;
  }

  th {
    background-color: #f4f4f4;
  }

  tr:nth-child(even) {
    background-color: #f9f9f9;
  }
`;
